-- Generated by `scrapagents generate-dbt` from configs/contracts/cyted/convocatorias.yml. Do not edit: change the contract and regenerate.
{{ config(tags=["source_cyted"]) }}

with source as (

    select * from {{ source('cyted', 'convocatorias') }}

),

records as (

    select
        payload as record,
        _batch_id::text as bronze_batch_id,
        _record_hash as bronze_record_hash,
        _landing_uri as bronze_landing_uri,
        _ingested_at as bronze_ingested_at
    from source

)

select
    (record ->> 'convocatoria_id')::text as convocatoria_id,
    (record ->> 'title')::text as title,
    (record ->> 'instrument')::text as instrument,
    (record ->> 'call_year')::bigint as call_year,
    (record ->> 'status')::text as status,
    (record ->> 'publication_date')::date as publication_date,
    (record ->> 'opening_date')::date as opening_date,
    (record ->> 'closing_date')::date as closing_date,
    (record ->> 'summary')::text as summary,
    record -> 'thematic_areas' as thematic_areas,
    (record ->> 'source_url')::text as source_url,
    (record ->> 'bases_document_url')::text as bases_document_url,
    record -> 'attachment_urls' as attachment_urls,
    (record ->> 'contact_email')::text as contact_email,
    bronze_batch_id,
    bronze_record_hash,
    bronze_landing_uri,
    bronze_ingested_at
from records
